import {section,table,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {jointFrame,bernoulliCdf,bernoulliCf} from './probability-model.js';
export const probabilitySections=[['questions','A distribution answers several questions'],['conditioning','Conditioning changes the reference population'],['total','Combine disjoint cases before reversing them'],['joint','Read a joint table in two directions'],['joint-lab','Move dependence while keeping marginals fixed'],['dependence','Zero covariance is not independence'],['cdf','Accumulate probability across a threshold'],['quantiles','Quantiles and inverse-transform sampling'],['empirical','Observed frequencies are an estimate'],['characteristic','The same distribution in frequency space'],['frequency-lab','Rotate outcomes, average their vectors'],['sums','Independent sums become products'],['moments','Moments require existence conditions'],['normality','Compare distributions, not only their covariance'],['practice','Choose the representation for the question'],['sources','Sources and connected owners']];
export const probabilityMeta={slug:'math/probability',title:'Probability and Distributions',description:'Conditioning, total probability, joint dependence, CDFs and quantiles, characteristic functions and their moment/test connections.',date:'2026-04-10',updated:'2026-10-11',topicPath:['math'],tags:['probability','Bayes','PMF','CDF','quantile','covariance','characteristic function','Epps-Pulley'],prototype:true,visibility:'public',kind:'dense-topic',related:['math/information','math/geometry'],learningGoals:['Weight conditional cases correctly','Distinguish marginals, dependence and covariance','Move between cumulative and frequency-space distributions']};
export const probabilityAliases=[];
const jointLab=`<div id="joint-lab" class="topic-scene" data-joint-lab><h3>Same marginals, different joint distributions</h3><p>X and Y are each Bernoulli(½). Moving c changes only how their outcomes pair. Table rows are X; columns are Y.</p><label>Covariance <output data-covariance>0.15</output><input type="range" min="-25" max="25" value="15" step="1" aria-label="Joint covariance in hundredths"></label>${table('Joint probability mass',['','Y=0','Y=1','P(X)'],[['X=0','<output data-cell="0">0.40</output>','<output data-cell="1">0.10</output>','0.50'],['X=1','<output data-cell="2">0.10</output>','<output data-cell="3">0.40</output>','0.50'],['P(Y)','0.50','0.50','1.00']])}<div class="scene-stats"><span>E[XY] <output data-exy>0.40</output></span><span>Correlation <output data-correlation>0.60</output></span><span>P(Y=1|X=1) <output data-conditional>0.80</output></span></div><p data-joint-caption>More mass is on equal outcomes: positive covariance.</p><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Exact four-cell family. At c=0 it is independent; this special binary family does not establish the reverse implication for all distributions.</p></div>`;
function phasorSvg(t,p){const unit=[Math.cos(t),Math.sin(t)],mean=bernoulliCf(t,p),point=(x,y)=>[150+110*x,150-110*y];return `<circle cx="150" cy="150" r="110" fill="none" stroke="#6e5165"/><path d="M20 150H280 M150 20V280" stroke="#53404f"/><line x1="150" y1="150" x2="260" y2="150" stroke="#bd738e" stroke-width="3" stroke-dasharray="7 4"/><line x1="150" y1="150" x2="${point(...unit)[0]}" y2="${point(...unit)[1]}" stroke="#bd738e" stroke-width="3" stroke-dasharray="7 4"/><line x1="260" y1="150" x2="${point(...unit)[0]}" y2="${point(...unit)[1]}" stroke="#73556a"/><line x1="150" y1="150" x2="${point(mean.re,mean.im)[0]}" y2="${point(mean.re,mean.im)[1]}" stroke="#bad6fa" stroke-width="5"/><circle cx="${point(mean.re,mean.im)[0]}" cy="${point(mean.re,mean.im)[1]}" r="6" fill="#bad6fa"/>`;}
const frequencyLab=`<div id="frequency-lab" class="topic-scene" data-frequency-lab><h3>Two views of one Bernoulli distribution</h3><p>Dashed burgundy vectors represent outcomes 0 and 1 on the unit circle. Solid blue is their probability-weighted mean φ(t), not another sample.</p><label>P(X=1) <output data-bernoulli-p>0.50</output><input type="range" min="0" max="100" value="50" step="1" aria-label="Bernoulli probability percent"></label><label>Frequency t <output data-frequency>0.80</output><input type="range" min="0" max="6.28" value="0.8" step="0.01" aria-label="Characteristic frequency"></label><div class="position-clock-layout"><svg viewBox="0 0 300 300" role="img" aria-label="Outcome unit vectors and their weighted characteristic mean">${phasorSvg(.8,.5)}</svg><div><div class="scene-stats"><span>Real <output data-real>0.8484</output></span><span>Imaginary <output data-imaginary>0.3587</output></span><span>Magnitude <output data-magnitude>0.9211</output></span></div><p>The mean stays inside the unit disk. Unequal phases can cancel even though probabilities are nonnegative.</p></div></div><label>CDF threshold x <output data-threshold>0.50</output><input type="range" min="-0.5" max="1.5" step="0.01" value="0.5" aria-label="CDF threshold"></label><p>F(x)=P(X≤x): <output data-cdf>0.50</output>. <span data-cdf-caption>Only outcome 0 is included.</span></p><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Playback sweeps frequency only. Threshold and frequency are independent views. This integer-support CF is periodic; one selected frequency cannot identify an arbitrary distribution.</p></div>`;
export function probabilityReader(link){return topic(probabilityMeta,probabilitySections,'One distribution; different views for cases, thresholds and sums.',`
<p>Probability calculations often fail before the arithmetic starts. A conditional probability uses a different reference population from a marginal probability. A density is not a point probability. Equal means and variances do not imply equal distributions.</p><p>Start with the question, then choose a representation. Cases help with conditioning. A joint table shows dependence. A CDF accumulates mass. A characteristic function turns random values into rotating vectors and makes sums easier to analyze.</p>
${section('questions','A distribution answers several questions',`${table('Choose the object by what it answers',['Object','Input and output','Useful question'],[['Probability mass function (PMF)','Value → nonnegative mass','How likely is this discrete outcome?'],['Probability density function (PDF)','Value → nonnegative density','How much probability is near this value?'],['Cumulative distribution function (CDF)','Threshold → probability','How much lies at or below x?'],['Joint distribution','Tuple → mass/density','How do outcomes occur together?'],['Characteristic function','Frequency → complex average','How do sums or distributional shapes behave?']])}<p>A random variable maps outcomes to numbers. Its distribution describes the probabilities of those numbers, not one realized sample. The same distribution can have several equivalent descriptions, but not every distribution has a density.</p>`)}
${section('conditioning','Conditioning changes the reference population',`${eq(String.raw`\begin{aligned}P(A\mid B)&=\frac{P(A\cap B)}{P(B)},\quad P(B)>0\\P(A\cap B)&=P(A\mid B)P(B)\end{aligned}`,'Conditioning restricts attention to outcomes in B, then renormalizes.')}
<p>P(A|B) and P(B|A) usually differ because their denominators differ. Independence means P(A∩B)=P(A)P(B). For positive P(B), it then gives P(A|B)=P(A). Mutually exclusive positive-probability events are not independent: observing one rules out the other.</p><p>A zero-probability condition cannot be handled by this elementary ratio. Conditioning on an exact continuous value needs the appropriate conditional-distribution construction.</p>`)}
${section('total','Combine disjoint cases before reversing them',`${eq(String.raw`\begin{aligned}P(A)&=\sum_i P(A\mid B_i)P(B_i)\\P(B_j\mid A)&=\frac{P(A\mid B_j)P(B_j)}{\sum_iP(A\mid B_i)P(B_i)}\end{aligned}`,'The Bᵢ form a mutually exclusive, exhaustive partition. Terms with zero case probability contribute zero; their undefined elementary conditional ratio is not evaluated.')}
<p>The first identity follows by writing A as the disjoint union of A∩Bᵢ. The second is Bayes' rule with that total as its normalizer. Conditional rates are weighted by case frequencies; an unweighted average is valid only for equal case probabilities.</p><p>Consider a hypothetical diagnostic test: prevalence 1%, sensitivity 99%, false-positive rate 2%. These are specified toy rates, not medical advice or a claim about a real test. Among 10,000 expected cases, 100 have the condition and 9,900 do not.</p>${table('Expected counts make the denominator visible',['Branch','Population','Positive rate','Expected positives'],[['Condition','100','.99','99'],['No condition','9,900','.02','198'],['Total','10,000','weighted total','297']])}${eq(String.raw`\begin{aligned}P(+)&=0.99(0.01)+0.02(0.99)=0.0297\\P(D\mid+)&=\frac{99}{297}=\frac13\end{aligned}`,'D denotes the condition and + a positive result. Sensitivity 99% is not a 99% posterior. Most positive results in this toy population are false positives because the condition is rare.')}
<p>Expected counts need not be integer realized counts in other examples. They are a convenient scale for the same probability calculation, not a guarantee about one sampled population.</p>`)}
${section('joint','Read a joint table in two directions',`${eq(String.raw`\begin{aligned}p_{ij}&=P(X=x_i,Y=y_j)\\P(X=x_i)&=\sum_j p_{ij}\\P(Y=y_j)&=\sum_i p_{ij}\\P(Y=y_j\mid X=x_i)&=\frac{p_{ij}}{\sum_k p_{ik}}\end{aligned}`,'Summing eliminates a variable. Conditioning selects a positive-mass row and renormalizes it.')}
<p>Check nonnegative entries and a total of one before using a table. Each marginal must also sum to one. The same law of total probability appears here: weighted conditional rows reconstruct the marginal of Y.</p>${eq(String.raw`\begin{aligned}\mathbb E[X]&=\sum_i x_iP(X=x_i)\\\mathbb E[Y]&=\sum_j y_jP(Y=y_j)\\\mathbb E[XY]&=\sum_{i,j}x_i y_j p_{ij}\\\operatorname{Cov}(X,Y)&=\mathbb E[(X-\mathbb E[X])(Y-\mathbb E[Y])]\\&=\mathbb E[XY]-\mathbb E[X]\mathbb E[Y]\end{aligned}`,'Assume the required expectations exist. Expand the centered product to obtain the shortcut.')}
<p>For binary X and Y, take ${inlineMath(String.raw`p_{00}=p_{11}=0.4`)} and ${inlineMath(String.raw`p_{01}=p_{10}=0.1`)}. Both means are .5, ${inlineMath(String.raw`\mathbb E[XY]=0.4`)}, and ${inlineMath(String.raw`\operatorname{Cov}(X,Y)=0.4-0.25=0.15`)}. The following family changes this association while keeping both marginals fixed.</p>${jointLab}`)}
${section('dependence','Zero covariance is not independence',`<p>Positive covariance indicates a positive signed linear association; negative covariance indicates the reverse. Zero covariance means the centered product has zero expectation, not that every form of dependence has vanished. Correlation divides covariance by the two standard deviations and is undefined if either is zero.</p><p>Take X uniform on {−1,0,1} and ${inlineMath(String.raw`Y=X^2`)}. Then ${inlineMath(String.raw`\mathbb E[X]=0,\quad\mathbb E[Y]=\frac23`)} and ${inlineMath(String.raw`\mathbb E[XY]=\mathbb E[X^3]=0`)}. Covariance is zero, yet Y is determined by X. The dependence is nonlinear.</p><p>Independence implies zero covariance when second moments are finite. The reverse is true under additional assumptions, such as jointly Gaussian variables. It is false in general.</p><p>A covariance matrix records pairwise second-order structure. Identity covariance means unit variances and zero cross-covariances, not necessarily independent or Gaussian coordinates. Sketched Isotropic Gaussian Regularization (SIGReg) compares projected distributions with a Gaussian target. Matching covariance alone cannot establish that target; we return to this distinction after introducing characteristic functions.</p>`)}
${section('cdf','Accumulate probability across a threshold',`${eq(String.raw`\begin{aligned}F(x)&=P(X\le x)\\P(a<X\le b)&=F(b)-F(a),\quad a\le b\end{aligned}`,'Endpoint inclusion matters at atoms. P(X=x)=F(x)−F(x−), where F(x−) is the left limit.')}
<p>For example, F(3)=0.8 means that 80% of the mass lies at or below 3.</p><p>A CDF is nondecreasing, right-continuous, takes values in [0,1], and tends to zero/one at the two infinities. Right-continuity fixes how jumps include their own value. It fully determines the distribution, including discrete, continuous and mixed cases.</p>${table('Fair die: cumulative steps',['Threshold','F(x)'],[['x&lt;1','0'],['1≤x&lt;2','1/6'],['2≤x&lt;3','2/6'],['3≤x&lt;4','3/6'],['4≤x&lt;5','4/6'],['5≤x&lt;6','5/6'],['x≥6','1']])}<p>For Uniform(0,1), F(x)=0 below zero, x between zero and one, and 1 above one. Thus P(.2&lt;X≤.7)=.7−.2=.5.</p>${eq(String.raw`\begin{aligned}\text{Discrete: }F(x)&=\sum_{t\le x}P(X=t)\\\text{With density }f:\;F(x)&=\int_{-\infty}^x f(t)\,dt\end{aligned}`,'For an absolutely continuous distribution, f=F′ almost everywhere. Differentiability alone at selected points does not ensure that the full CDF is recovered by integrating those derivatives.')}
<p>A PDF can exceed one; interval area, not height alone, is probability. For a distribution with a density, exact points have zero probability. An atom is different: its CDF jumps. A general continuous CDF can also be singular, so “continuous” is not automatically “has a PDF.”</p>`)}
${section('quantiles','Quantiles and inverse-transform sampling',`${eq(String.raw`\begin{aligned}Q(u)&=\inf\{x:F(x)\ge u\},\quad0<u<1\\U&\sim\operatorname{Uniform}(0,1)\\&\Longrightarrow Q(U)\text{ has CDF }F\end{aligned}`,'This generalized inverse works for jumps and flat regions. It does not require a strictly increasing CDF.')}
<p>A fair die has ${inlineMath(String.raw`Q(u)=\lceil6u\rceil,\quad0<u<1`)}. Intervals of u with width 1/6 select each face. The cumulative mass at a discrete quantile can exceed the requested level because the CDF jumps there.</p><p>The 95th percentile is the lower threshold whose cumulative mass reaches .95 under this convention. It need not have exactly 95% below it. Sample-percentile libraries may interpolate using different conventions; record the chosen one.</p><p>Uniform endpoints have probability zero in the continuous idealization, but software can produce boundary values. For the finite-support helper used here, zero selects the first positive-mass value and one selects the last. Zero-mass entries are never returned. Tiny cumulative rounding errors use the last positive-mass value, not an unused trailing category.</p>`)}
${section('empirical','Observed frequencies are an estimate',`${eq(String.raw`F_n(x)=\frac1n\sum_{j=1}^n\mathbf1\{X_j\le x\}`,'Count observations at or below the threshold, then divide by sample size.')}
<p>For [1,2,2,5], ${inlineMath(String.raw`F_n(2)=\frac34`)}. The repeated value creates a jump of 2/4 at 2. Ties should be counted, not silently deduplicated.</p><p>Empirical CDFs support percentile lookup, interval counts and distribution comparisons. The Kolmogorov–Smirnov statistic uses the largest CDF discrepancy. Its usual calibration assumes particular sampling and null conditions; fitted parameters or ties can require different calibration.</p><p>Data dependence, selection bias and a small sample can make an empirical view misleading. A smooth plot is not evidence that the sample represents the population.</p>`)}
${section('characteristic','The same distribution in frequency space',`<p>A CDF answers threshold questions directly. For a sum of random variables, combining many thresholds becomes cumbersome. Frequency space offers another complete representation: rotate each value into a unit vector, then average.</p>${eq(String.raw`\begin{aligned}\varphi_X(t)&=\mathbb E[e^{itX}]\\&=\mathbb E[\cos(tX)]+i\mathbb E[\sin(tX)]\end{aligned}`,`t is a frequency and ${inlineMath(String.raw`i^2=-1`)}. Every outcome contributes a unit-circle vector; average with its probability.`)}
<p>The characteristic function always exists because the complex exponential has magnitude one. In particular φ(0)=1, |φ(t)|≤1 and φ(−t)=conjugate(φ(t)). Negative real parts or imaginary components are not negative probabilities; they are averages of oscillating coordinates.</p>${table('Exact examples',['Distribution','Characteristic function'],[['Constant X=c',inlineMath(String.raw`e^{itc}`)],['Bernoulli(p)',inlineMath(String.raw`1-p+pe^{it}`)],['Standard normal',inlineMath(String.raw`e^{-t^2/2}`)],['Normal(μ,σ²)',inlineMath(String.raw`e^{it\mu-\sigma^2t^2/2}`)]])}<p>The full function uniquely determines the distribution. Matching a few frequencies does not. Small t emphasizes slower oscillation and, when moments exist, its local derivatives encode them. Larger |t| can reveal fine structure, but “global versus local” is an intuition, not a universal recovery guarantee.</p>${frequencyLab}`)}
${section('sums','Independent sums become products',`${eq(String.raw`\begin{aligned}\varphi_{X+Y}(t)&=\mathbb E[e^{itX}e^{itY}]\\&=\mathbb E[e^{itX}]\mathbb E[e^{itY}]\\&=\varphi_X(t)\varphi_Y(t)\end{aligned}`,'The factorization uses independence. Without it, the joint characteristic function is needed.')}
<p>Convolution in value space becomes multiplication in frequency space. For independent normals, multiplying the two exponential forms adds their means and variances. For n independent Bernoulli(p) trials, ${inlineMath(String.raw`(1-p+pe^{it})^n`)} describes their binomial sum.</p><p>An affine transformation also has a simple form: ${inlineMath(String.raw`\varphi_{aX+b}(t)=e^{itb}\varphi_X(at)`)}. Here a and b are fixed real constants. Shifting adds phase; scaling changes the frequency argument. This makes the representation convenient for algebra, not only for plots.</p>`)}
${section('moments','Moments require existence conditions',`${eq(String.raw`\begin{aligned}\mathbb E[|X|^k]<\infty&\Longrightarrow\varphi_X^{(k)}(0)=i^k\mathbb E[X^k]\\\mathbb E[X]&=\frac{\varphi_X'(0)}{i}\\\mathbb E[X^2]&=-\varphi_X''(0)\end{aligned}`,'Finite absolute moments justify exchanging differentiation and expectation. Do not infer all moments from the existence of φ itself.')}
<p>Variance is E[X²]−E[X]² when these moments exist. A characteristic function can exist even when the mean or variance does not. Moment-generating functions E[eᵗˣ] lack the bounded complex-exponential argument and may fail to exist around zero.</p><p>For a vector X, ${inlineMath(String.raw`\varphi_X(t)=\mathbb E[e^{i t^\top X}]`)} uses a vector frequency of the same dimension. The dot product gives the scalar phase. Individual projected distributions examine directions, while a covariance matrix captures only second-order structure.</p>`)}
${section('normality','Compare distributions, not only their covariance',`${eq(String.raw`\widehat\varphi_{X,n}(t)=\frac1n\sum_{j=1}^n e^{itX_j}`,'The empirical characteristic function replaces an expectation with a finite average.')}
<p>The full characteristic function contains more than means and covariance. We can therefore compare distributional shape, including departures that those summaries miss.</p><p>For a normality comparison, standardize observations ${inlineMath(String.raw`Y_j=\frac{X_j-\bar X}{S}`)} with positive scale S. Recompute the empirical function from Y rather than X: replace Xⱼ with Yⱼ in the displayed average. Compare this standardized function with the standard-normal target. A constant sample has S=0 and requires a separate policy.</p>${eq(String.raw`T_n=n\int_{-\infty}^{\infty}\left|\widehat\varphi_{Y,n}(t)-e^{-t^2/2}\right|^2w(t)\,dt`,'The Epps–Pulley family uses a nonnegative frequency weight. Larger mismatch gives a larger statistic, not automatically a calibrated probability.')}
<p>The integrand is the squared complex distance at one frequency. Weighting and integrating combines these mismatches. Gaussian weights emphasize a frequency range and make the integral reducible to finite sums through Gaussian Fourier identities. Weight bandwidth affects sensitivity; high-frequency empirical oscillations should not be interpreted as pure population structure.</p><p>Mean/scale estimation, sample size, standardization convention and the null model affect test calibration. Do not attach a p-value without the corresponding procedure. Failure to reject is not proof of normality.</p><p>Distributional regularizers can borrow this comparison idea without being a classical hypothesis test. <a href="${link('models/vision')+'#gaussian-target'}">Projected Gaussian regularization →</a> applies frequency-space comparisons to projected embeddings. An optimization penalty and a calibrated statistical test have different uses.</p>`)}
${section('practice','Choose the representation for the question',`${table('A small probability workflow',['Question','First operation','Check'],[['Different scenarios','Partition and weight conditional rates','Disjoint and exhaustive cases'],['Reverse a condition','Bayes numerator / total denominator','Base rates and positive denominator'],['Joint variability','Marginals, E[XY], centered product','Finite moments; units; not independence'],['Intervals or percentiles','CDF difference or generalized inverse','Open/closed endpoints and quantile convention'],['Sums or affine changes','Characteristic multiplication / argument transform','Independence and moment conditions'],['Distributional mismatch','CDF or frequency comparison','Sampling and statistical calibration']])}<p>Expectation, counting, stopping rules and Poisson arrival models are grouped in the <a href="${link('math/problem-solving')}">Mathematical Problem Solving →</a>. Linearity of expectation does not require independence; a Poisson arrival model does require its process assumptions. Those distinctions belong with the problem-solving workflow, not another isolated probability page.</p><p><a href="${link('math/information')}">Information Theory →</a> then asks how much coding or predictive uncertainty a distribution contains. Probability defines the distribution first; entropy is a functional of it, not a replacement for the full distribution.</p>`)}
${section('sources','Sources and connected owners',`<p>${cite('https://www.statlect.com/fundamentals-of-probability/characteristic-function','Characteristic functions: definition and conditions')} · ${cite('https://doi.org/10.1093/biomet/70.3.723','Epps and Pulley (1983)')}</p><div class="dense-related"><a href="${link('math/information')}">Information Theory →</a><a href="${link('math/geometry')}">Unit embeddings and geometry →</a><a href="${link('models/vision')+'#gaussian-target'}">Gaussian target in vision →</a></div>`)}
`);}
probabilityMeta.searchText=probabilityReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountProbability(scope=document){mountTopic(scope,probabilityMeta.slug,article=>{
 const joint=article.querySelector('[data-joint-lab]');rangePlayback(article,joint,cents=>{const f=jointFrame(cents/100);joint.querySelector('[data-covariance]').textContent=f.cov.toFixed(2);f.cells.flat().forEach((v,i)=>{const cell=joint.querySelector(`[data-cell="${i}"]`);cell.textContent=v.toFixed(2);cell.closest('td').style.background=`rgba(186,214,250,${v})`;});for(const [key,v]of [['exy',f.exy],['correlation',f.correlation],['conditional',f.conditional]])joint.querySelector(`[data-${key}]`).textContent=v.toFixed(2);joint.querySelector('[data-joint-caption]').textContent=cents>0?'More mass is on equal outcomes: positive covariance.':cents<0?'More mass is on unequal outcomes: negative covariance.':'All cells have mass .25: X and Y are independent in this family.';},16000);
 const lab=article.querySelector('[data-frequency-lab]'),sliders=lab.querySelectorAll('input[type="range"]'),p=sliders[0],threshold=sliders[2];
 // Playback owns frequency, not the probability or the CDF threshold.
 const frequency=sliders[1];const controls=rangePlayback(article,lab,t=>{const prob=Number(p.value)/100,x=Number(threshold.value),f=bernoulliCf(t,prob);lab.querySelector('svg').innerHTML=phasorSvg(t,prob);for(const [key,v,places]of [['bernoulli-p',prob,2],['frequency',t,2],['real',f.re,4],['imaginary',f.im,4],['magnitude',Math.hypot(f.re,f.im),4],['threshold',x,2],['cdf',bernoulliCdf(x,prob),2]])lab.querySelector(`[data-${key}]`).textContent=v.toFixed(places);lab.querySelector('[data-cdf-caption]').textContent=x<0?'No outcome is included.':x<1?'Only outcome 0 is included.':'Both outcomes are included.';},16000,frequency);
 for(const slider of [p,threshold])slider.addEventListener('input',()=>{controls.stop();controls.render();});
});}
